    doThrow(new RuntimeException()).when(eventStore).appendAll(anyList());
    when(eventStore.getEventsOfAggregate(any())).thenReturn(History.empty());
    DataCollectorSubscriber subscriber = new DataCollectorSubscriber();
    EventSourcingSystem eventSourcingSystem = new EventSourcingSystem(ImmutableSet.of(simpleDispatcher(eventStore)), ImmutableSet.of(events -> {
        throw new RuntimeException();
    }, subscriber), eventStore);
    assertThatThrownBy(() -> eventSourcingSystem.dispatch(new MyCommand(PAYLOAD_1))).isInstanceOf(RuntimeException.class);
    assertThat(subscriber.getData()).isEmpty();
}

