    CountDownLatch latch = new CountDownLatch(1);
    doAnswer(invocation -> {
        latch.await();
        return null;
    }).when(listener).event(EVENT);
    assertTimeout(Duration.ofSeconds(2), () -> {
        eventBus().dispatch(EVENT, NO_KEYS).block();
        latch.countDown();
    });
}

