public void otherAttachmentsShouldBeenIndexedWhenOneOfThemCannotBeParsed() throws Exception {
    //Given
    MailboxMessage mailboxMessage = mock(MailboxMessage.class);
    TestId mailboxId = TestId.of(1);
    when(mailboxMessage.getMailboxId()).thenReturn(mailboxId);
    when(mailboxMessage.getMessageId()).thenReturn(InMemoryMessageId.of(42));
    when(mailboxMessage.getFullContent()).thenReturn(ClassLoader.getSystemResourceAsStream("eml/emailWith3Attachments.eml"));
    when(mailboxMessage.createFlags()).thenReturn(new Flags());
    when(mailboxMessage.getUid()).thenReturn(MESSAGE_UID);
    TextExtractor textExtractor = mock(TextExtractor.class);
    when(textExtractor.extractContent(any(), any())).thenReturn(new ParsedContent(Optional.of("first attachment content"), ImmutableMap.of())).thenThrow(new RuntimeException("second cannot be parsed")).thenReturn(new ParsedContent(Optional.of("third attachment content"), ImmutableMap.of()));
    // When
    IndexableMessage indexableMessage = IndexableMessage.builder().message(mailboxMessage).users(ImmutableList.of(User.fromUsername("username"))).extractor(textExtractor).zoneId(ZoneId.of("Europe/Paris")).indexAttachments(IndexAttachments.YES).build();
    // Then
    assertThat(indexableMessage.getAttachments()).extracting(new TextualBodyExtractor()).contains("first attachment content", TextualBodyExtractor.NO_TEXTUAL_BODY, "third attachment content");
}

