    webAdminServer.configure(NO_CONFIGURATION);
    webAdminServer.await();
    RestAssured.requestSpecification = WebAdminUtils.buildRequestSpecification(webAdminServer).setBasePath(CassandraMigrationRoutes.VERSION_BASE).build();
}

