@Test
void getDomainMappingsEmptyMappingsAreFilteredOut() throws RecipientRewriteTableException {
    MappingSource nonEmptyMapping = MappingSource.fromDomain(Domain.of("abc.com"));
    MappingSource emptyMapping = MappingSource.fromDomain(Domain.of("def.com"));
    Map<MappingSource, Mappings> mappings = ImmutableMap.of(nonEmptyMapping, MappingsImpl.fromRawString("domain:a.com"), emptyMapping, MappingsImpl.empty());
    when(recipientRewriteTable.getAllMappings()).thenReturn(mappings);
    Map<String, List<String>> map = when().get().then().contentType(ContentType.JSON).statusCode(HttpStatus.OK_200).extract().body().jsonPath().getMap(".");
    assertThat(map).containsKey(nonEmptyMapping.asString()).doesNotContainKey(emptyMapping.asString());
}

