    JsonTransformer jsonTransformer = new JsonTransformer();
    webAdminServer = WebAdminUtils.createWebAdminServer(new DefaultMetricFactory(), new TasksRoutes(taskManager, jsonTransformer), new ReindexingRoutes(taskManager, mailboxIdFactory, reIndexer, jsonTransformer), new MessageIdReindexingRoutes(taskManager, new InMemoryMessageId.Factory(), new MessageIdReIndexerImpl(mailboxManager, mailboxManager.getMapperFactory(), searchIndex), jsonTransformer));
    webAdminServer.configure(NO_CONFIGURATION);
