}

@Test
public void listMailRepositoriesShouldReturnEmptyWhenEmpty() {
    when(mailRepositoryStore.getPaths()).thenReturn(Stream.empty());
    assertThat(testee.listMailRepositories()).isEmpty();
}

@Test
public void listMailRepositoriesShouldReturnOneRepositoryWhenOne() {
    when(mailRepositoryStore.getPaths()).thenReturn(Stream.of(FIRST_REPOSITORY_PATH));
    assertThat(testee.listMailRepositories()).extracting(SingleMailRepositoryResponse::getRepository).containsOnly(FIRST_REPOSITORY_PATH.asString());
}

@Test
public void listMailRepositoriesShouldReturnTwoRepositoriesWhentwo() {
    when(mailRepositoryStore.getPaths()).thenReturn(Stream.of(FIRST_REPOSITORY_PATH, SECOND_REPOSITORY_PATH));
    assertThat(testee.listMailRepositories()).extracting(SingleMailRepositoryResponse::getRepository).containsOnly(FIRST_REPOSITORY_PATH.asString(), SECOND_REPOSITORY_PATH.asString());
}

@Test
public void listMailsShouldThrowWhenMailRepositoryStoreThrows() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenThrow(new MailRepositoryStore.MailRepositoryStoreException("message"));
    assertThatThrownBy(() -> testee.listMails(FIRST_REPOSITORY_PATH, Offset.none(), Limit.unlimited())).isInstanceOf(MailRepositoryStore.MailRepositoryStoreException.class);
}

@Test
public void listMailsShouldReturnEmptyWhenMailRepositoryIsEmpty() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    assertThat(testee.listMails(FIRST_REPOSITORY_PATH, Offset.none(), Limit.unlimited()).get()).isEmpty();
}

@Test
public void listMailsShouldReturnContainedMailKeys() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    repository.store(FakeMail.builder().name(NAME_1.asString()).build());
    repository.store(FakeMail.builder().name(NAME_2.asString()).build());
    assertThat(testee.listMails(FIRST_REPOSITORY_PATH, Offset.none(), Limit.unlimited()).get()).containsOnly(new MailKeyDTO(NAME_1), new MailKeyDTO(NAME_2));
}

@Test
public void listMailsShouldApplyLimitAndOffset() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    repository.store(FakeMail.builder().name(NAME_1.asString()).build());
    repository.store(FakeMail.builder().name(NAME_2.asString()).build());
    repository.store(FakeMail.builder().name("name3").build());
    assertThat(testee.listMails(FIRST_REPOSITORY_PATH, Offset.from(1), Limit.from(1)).get()).containsOnly(new MailKeyDTO(NAME_2));
}

@Test
public void retrieveMessageShouldThrownWhenUnknownRepository() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of());
    assertThatThrownBy(() -> testee.retrieveMessage(FIRST_REPOSITORY_PATH, NAME_1)).isNotInstanceOf(NullPointerException.class);
}

@Test
public void retrieveMessageShouldThrowWhenMailRepositoryStoreThrows() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenThrow(new MailRepositoryStore.MailRepositoryStoreException("message"));
    assertThatThrownBy(() -> testee.retrieveMessage(FIRST_REPOSITORY_PATH, NAME_1)).isInstanceOf(MailRepositoryStore.MailRepositoryStoreException.class);
}

@Test
public void retrieveMessageShouldReturnEmptyWhenMailNotFound() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    assertThat(testee.retrieveMessage(FIRST_REPOSITORY_PATH, NAME_1)).isEmpty();
}

@Test
public void retrieveMessageShouldReturnTheMessageWhenMailExists() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    FakeMail mail = FakeMail.builder().name(NAME_1.asString()).fileName("mail.eml").build();
    repository.store(mail);
    Optional<MimeMessage> mimeMessage = testee.retrieveMessage(FIRST_REPOSITORY_PATH, NAME_1);
    assertThat(mimeMessage).isNotEmpty();
    String eml = IOUtils.toString(new MimeMessageInputStream(mimeMessage.get()), StandardCharsets.UTF_8);
    String expectedContent = ClassLoaderUtils.getSystemResourceAsString("mail.eml");
    assertThat(eml).isEqualToNormalizingNewlines(expectedContent);
}

